code='''from collections import Counter

def transform(grid):
    g=[row[:] for row in grid]
    bg=g[0][0]
    key_row=next(r for r in range(len(g)-1,-1,-1) if any(v!=bg for v in g[r]))
    seq=[v for v in g[key_row] if v!=bg]
    border=Counter(v for r,row in enumerate(g) for v in row if v!=bg and r!=key_row).most_common(1)[0][0]
    seen=set(); markers=[]
    for r in range(key_row):
        for c,v in enumerate(g[r]):
            if v in (bg,border) or (r,c) in seen: continue
            todo=[(r,c)]; seen.add((r,c)); cells=[]
            while todo:
                x,y=todo.pop(); cells.append((x,y))
                for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0<=nx<key_row and 0<=ny<len(g[0]) and (nx,ny) not in seen and g[nx][ny]==v:
                        seen.add((nx,ny)); todo.append((nx,ny))
            markers.append((v,(min(x for x,y in cells),max(x for x,y in cells),min(y for x,y in cells),max(y for x,y in cells))))
    used=set()
    for a,b in zip(seq,seq[1:]):
        ai=next(i for i,(v,box) in enumerate(markers) if v==a and i not in used)
        used.add(ai)
        bi=next(i for i,(v,box) in enumerate(markers) if v==b and i not in used)
        r1,r2,c1,c2=markers[ai][1]; s1,s2,d1,d2=markers[bi][1]
        if r1==s1:
            for r in range(r1,r2+1):
                for c in range(min(c1,d1),max(c2,d2)+1): g[r][c]=a
        else:
            for r in range(min(r1,s1),max(r2,s2)+1):
                for c in range(c1,c2+1): g[r][c]=a
    return g
'''
